WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET PAGESIZE 100
SET LINESIZE 180
SET FEEDBACK ON
SET DEFINE OFF

COLUMN category_code FORMAT A16
COLUMN category_name FORMAT A24
COLUMN status FORMAT A16
COLUMN priority FORMAT A10

PROMPT Relatorio 1 - ocorrencias por categoria
SELECT c.code AS category_code,
       c.name AS category_name,
       COUNT(o.id) AS occurrence_count
  FROM categories c
  LEFT JOIN occurrences o
    ON o.category_id = c.id
   AND RAWTOHEX(o.id) IN (
       'A0000000000000000000000000000001', 'A0000000000000000000000000000002',
       'A0000000000000000000000000000003', 'A0000000000000000000000000000004',
       'A0000000000000000000000000000005', 'A0000000000000000000000000000006',
       'A0000000000000000000000000000007', 'A0000000000000000000000000000008',
       'A0000000000000000000000000000009', 'A000000000000000000000000000000A',
       'A000000000000000000000000000000B', 'A000000000000000000000000000000C'
   )
 WHERE RAWTOHEX(c.id) IN (
       '11111111111111111111111111111111', '22222222222222222222222222222222',
       '33333333333333333333333333333333', '44444444444444444444444444444444',
       '55555555555555555555555555555555', '66666666666666666666666666666666'
   )
 GROUP BY c.code, c.name
 ORDER BY c.code;

PROMPT Relatorio 2 - fila nao terminal por prioridade
SELECT priority,
       COUNT(*) AS occurrence_count
  FROM occurrences
 WHERE status NOT IN ('ENCERRADA', 'CANCELADA')
   AND RAWTOHEX(id) IN (
       'A0000000000000000000000000000001', 'A0000000000000000000000000000002',
       'A0000000000000000000000000000003', 'A0000000000000000000000000000004',
       'A0000000000000000000000000000005', 'A0000000000000000000000000000006',
       'A0000000000000000000000000000007', 'A0000000000000000000000000000008',
       'A0000000000000000000000000000009', 'A000000000000000000000000000000A',
       'A000000000000000000000000000000B', 'A000000000000000000000000000000C'
   )
 GROUP BY priority
 ORDER BY CASE priority
              WHEN 'CRITICA' THEN 1
              WHEN 'ALTA' THEN 2
              WHEN 'MEDIA' THEN 3
              WHEN 'BAIXA' THEN 4
          END;

PROMPT Relatorio 3 - categoria e status
SELECT c.code AS category_code,
       o.status,
       COUNT(*) AS occurrence_count
  FROM occurrences o
  JOIN categories c ON c.id = o.category_id
 WHERE RAWTOHEX(o.id) IN (
       'A0000000000000000000000000000001', 'A0000000000000000000000000000002',
       'A0000000000000000000000000000003', 'A0000000000000000000000000000004',
       'A0000000000000000000000000000005', 'A0000000000000000000000000000006',
       'A0000000000000000000000000000007', 'A0000000000000000000000000000008',
       'A0000000000000000000000000000009', 'A000000000000000000000000000000A',
       'A000000000000000000000000000000B', 'A000000000000000000000000000000C'
   )
 GROUP BY c.code, o.status
 ORDER BY c.code, o.status;
